const CATEGORY_LABEL: Record<SettingsCategory, string> = {
  appearance: ja.settings.appearanceSection,
  playback: ja.settings.playbackSection,
  recordings: ja.settings.recordingsSection,
  transcription: ja.settings.transcriptionSection,
  score: ja.settings.scoreSection,
  export: ja.settings.exportSection,
  tools: ja.settings.toolsSection,
  advanced: ja.settings.advancedSection,
};

function toolBadge(info: ToolInfo | undefined): {
  tone: StatusTone;
  label: string;
} {
  const s = ja.dependencies;
  const status = info?.status ?? "checking";
  return status === "found"
    ? { tone: "success", label: s.statusFound }
    : status === "missing"
      ? { tone: "error", label: s.statusMissing }
      : status === "checking"
        ? { tone: "info", label: s.statusChecking }
        : { tone: "neutral", label: ja.diagnostics.unknown };
}

/**
 * Editable path field (tool locations, 既定の保存先). The draft commits on
 * blur/Enter so every keystroke does not re-probe tool status.
 */
function PathField({
  label,
  value,
  placeholder,
  onCommit,
  trailing,
}: {
  label: string;
  value: string;
  placeholder?: string;
  onCommit(value: string): void;
  trailing?: React.ReactNode;
}) {
  const id = useId();
  const [draft, setDraft] = useState(value);
  useEffect(() => setDraft(value), [value]);
  const commit = () => {
    if (draft !== value) onCommit(draft);
  };
  return (
    <div className="hs-settings__field">
      <Label id={id}>{label}</Label>
      <div className="hs-settings__path-row">
        <Input
          aria-labelledby={id}
          value={draft}
          placeholder={placeholder}
          onChange={(_, d) => setDraft(d.value)}
          onBlur={commit}
          onKeyDown={(ev) => {
            if (ev.key === "Enter") commit();
          }}
        />
        {trailing}
      </div>
    </div>
  );
}

/**
 * 設定 — auxiliary screen, not a work mode (GUI_UX_SPEC §18; issue UI-060).
 *
 * Left nav lists the categories (外観/再生/録音/採譜/楽譜/書き出し/ツール/
 * 詳細設定); only the selected panel renders, so advanced settings never
 * leak into the workspace. There is intentionally NO language setting —
 * the UI is Japanese-only by contract.
 *
 * Values persist to localStorage immediately (same precedent as the theme
 * switcher). Tool paths are user-editable; a non-empty path wins over
 * auto-detection in the diagnostics probe.
 */
export function SettingsView({
  themeMode,
  onThemeMode,
  onBack,
  settings,
  onSettingsChange,
  diagnosticsPort,
  exportPort,
  onOpenDiagnostics,
  onAnnounce,
  focusCategory,
}: {
  themeMode: ThemeMode;
  onThemeMode(m: ThemeMode): void;
  onBack(): void;
  settings: AppSettings;
  onSettingsChange(patch: Partial<AppSettings>): void;
  diagnosticsPort: DiagnosticsPort;
  exportPort: ExportPort;
  onOpenDiagnostics(): void;
  /** Status-bar announcements (role="status" is aria-live). */
  onAnnounce(message: string): void;
  /** Deep-link target (e.g. "export" from the MuseScore recovery action). */
  focusCategory?: SettingsCategory;
}) {
  const s = ja.settings;
  const [category, setCategory] = useState<SettingsCategory>(
    focusCategory ?? "appearance",
  );
  useEffect(() => {
    if (focusCategory) setCategory(focusCategory);
  }, [focusCategory]);

  // Tool status / paths for ツール + 詳細設定 — collected once, then again
  // whenever the user commits a different tool path (the override flips
  // the reported status to 検出済み).
  const [diag, setDiag] = useState<DiagnosticsInfo | null>(null);
  useEffect(() => {
    let cancelled = false;
    void diagnosticsPort
      .collect({
        museScorePath: settings.museScorePath,
        ffmpegPath: settings.ffmpegPath,
      })
      .then((info) => {
        if (!cancelled) setDiag(info);
      })
      .catch(() => undefined);
    return () => {
      cancelled = true;
    };
  }, [diagnosticsPort, settings.museScorePath, settings.ffmpegPath]);

  const pickExportDir = useCallback(async () => {
    try {
      const dir = await exportPort.chooseDestination(
        settings.defaultExportDir || undefined,
      );
      if (dir) onSettingsChange({ defaultExportDir: dir });
    } catch {
      /* picker unavailable (unsupported port) — the field stays editable */
    }
  }, [exportPort, settings.defaultExportDir, onSettingsChange]);

  const museBadge = toolBadge(diag?.tools.museScore);
  const ffmpegBadge = toolBadge(diag?.tools.ffmpeg);

  const openLogs = useCallback(async () => {
    const ok = await diagnosticsPort.openLogFolder();
    if (!ok) {
      // Honest feedback — the shell has no folder bridge yet.
      onAnnounce(ja.diagnostics.openLogsFailed);
    }
  }, [diagnosticsPort, onAnnounce]);

  // #78: 録音ファイル管理 — カテゴリを開いた時に情報を取り直す。
  const [recInfo, setRecInfo] = useState<RecordingsInfo | null>(null);
  const [recFiles, setRecFiles] = useState<RecordingFile[] | null>(null);
  const [clearConfirmOpen, setClearConfirmOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<string | null>(null);
  const refreshRecordings = useCallback(() => {
    void getRecordingsInfo().then(setRecInfo);
    void listRecordings().then(setRecFiles);
  }, []);
  useEffect(() => {
    if (category === "recordings") refreshRecordings();
  }, [category, refreshRecordings]);

  const section = (() => {
    switch (category) {
      case "appearance":
        return (
          <>
            <Label id="hs-theme-label">{s.themeLabel}</Label>
            <RadioGroup
              aria-labelledby="hs-theme-label"
              value={themeMode}
              onChange={(_, data) => onThemeMode(data.value as ThemeMode)}
            >
              <Radio value="system" label={s.themeSystem} />
              <Radio value="light" label={s.themeLight} />
              <Radio value="dark" label={s.themeDark} />
            </RadioGroup>
          </>
        );

      case "playback":
        return (
          <>
            <HsSelect
              label={s.defaultRate}
              value={String(settings.playbackRate)}
              options={playbackRateOptions().map((r) => ({
                value: String(r),
                label: `${r}×`,
              }))}
              onChange={(v) =>
                onSettingsChange({ playbackRate: Number(v) })
              }
            />
            <HsNumericField
              label={s.skipSeconds}
              value={settings.skipSeconds}
              min={1}
              max={60}
              step={1}
              unit={s.secondsUnit}
              onChange={(v) =>
                v != null && onSettingsChange({ skipSeconds: v })
              }
            />
            <Checkbox
              checked={settings.followPlayback}
              onChange={(_, d) =>
                onSettingsChange({ followPlayback: d.checked === true })
              }
              label={s.followPlayback}
            />
          </>
        );

      case "recordings":
        return (
          <>
            <div className="hs-settings__field">
              <Label>{s.recordingsFolder}</Label>
              <div className="hs-settings__path-row">
                <p className="hs-settings__value">
                  {recInfo?.dir ?? ja.diagnostics.notConnected}
                </p>
                <HsButton
                  size="small"
                  disabled={!recInfo}
                  onClick={() => {
                    void openRecordingsDir().then((ok) => {
                      if (!ok) onAnnounce(s.recordingsUnavailable);
                    });
                  }}
                >
                  {s.recordingsOpen}
                </HsButton>
              </div>
            </div>
            <div className="hs-settings__field">
              <Label>{s.recordingsSection}</Label>
              <div className="hs-settings__path-row">
                <p className="hs-settings__value">
                  {recInfo
                    ? recInfo.fileCount > 0
                      ? `${s.recordingsCount(recInfo.fileCount)} — ${formatBytes(recInfo.totalBytes)}`
                      : s.recordingsEmpty
                    : s.recordingsUnavailable}
                </p>
                <HsButton
                  size="small"
                  disabled={!recInfo || recInfo.fileCount === 0}
                  onClick={() => setClearConfirmOpen(true)}
                >
                  {s.recordingsClear}
                </HsButton>
              </div>
            </div>
            {/* #78: 個別削除 — 全削除だけだと「残したい録音」も消える。 */}
            {recFiles && recFiles.length > 0 && (
              <div className="hs-settings__field">
                <ul className="hs-settings__recording-list">
                  {recFiles.map((f) => (
                    <li key={f.name} className="hs-settings__recording-item">
                      <span className="hs-settings__recording-name">
                        {f.name}
                      </span>
                      <span className="hs-settings__recording-size">
                        {formatBytes(f.bytes)}
                      </span>
                      <HsButton
                        size="small"
                        variant="secondary"
                        onClick={() => setDeleteTarget(f.name)}
                      >
                        {s.recordingsDelete}
                      </HsButton>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {/* #87: 保持日数ポリシー — 起動時に古いWAVを自動削除。 */}
            <HsSelect
              label={s.recordingsRetention}
              value={String(settings.recordingsRetentionDays)}
              options={[0, 7, 30, 90].map((d) => ({
                value: String(d),
                label:
                  d === 0
                    ? s.recordingsRetentionNever
                    : s.recordingsRetentionDays(d),
              }))}
              onChange={(v) =>
                onSettingsChange({ recordingsRetentionDays: Number(v) })
              }
            />
          </>
        );

      case "transcription":
        return (
          <>
            <HsSelect
              label={s.tempo}
              value={settings.tempoMode}
              options={[
                { value: "auto", label: s.tempoAuto },
                { value: "manual", label: s.tempoManual },
              ]}
              onChange={(v) =>
                onSettingsChange({
                  tempoMode: v === "manual" ? "manual" : "auto",
                })
              }
            />
            <HsNumericField
              label={s.bpm}
              value={settings.bpm}
              min={30}
              max={300}
              step={1}
              disabled={settings.tempoMode === "auto"}
              onChange={(v) => v != null && onSettingsChange({ bpm: v })}
            />
            <HsSelect
              label={s.meter}
              value={settings.meter}
              options={[
                { value: "auto", label: s.tempoAuto },
                { value: "4/4", label: "4/4" },
                { value: "3/4", label: "3/4" },
                { value: "6/8", label: "6/8" },
                { value: "2/4", label: "2/4" },
                { value: "5/4", label: "5/4" },
              ]}
              onChange={(v) =>
                onSettingsChange({
                  meter: v as AppSettings["meter"],
                })
              }
            />
            <HsSelect
              label={s.minDuration}
              value={settings.minDuration}
              options={[
                { value: "eighth", label: s.minDurationEighth },
                { value: "sixteenth", label: s.minDurationSixteenth },
                {
                  value: "thirtySecond",
                  label: s.minDurationThirtySecond,
                },
              ]}
              onChange={(v) =>
                onSettingsChange({
                  minDuration: v as AppSettings["minDuration"],
                })
              }
            />
            <Checkbox
              checked={settings.triplets}
              onChange={(_, d) =>
                onSettingsChange({ triplets: d.checked === true })
              }
              label={s.tripletsAllow}
            />
          </>
        );

      case "score":
        return (
          <HsSelect
            label={s.initialView}
            value={settings.scoreInitialView}
            options={[
              { value: "continuous", label: s.viewContinuous },
              { value: "page", label: s.viewPage },
            ]}
            onChange={(v) =>
              onSettingsChange({
                scoreInitialView: v === "page" ? "page" : "continuous",
              })
            }
          />
        );

      case "export":
        return (
          <>
            <PathField
              label={s.defaultFolder}
              value={settings.defaultExportDir}
              placeholder={s.folderPlaceholder}
              onCommit={(v) => onSettingsChange({ defaultExportDir: v })}
              trailing={
                <HsButton size="small" onClick={() => void pickExportDir()}>
                  {ja.common.browse}
                </HsButton>
              }
            />
            <PathField
              label={s.musescorePath}
              value={settings.museScorePath}
              placeholder={s.pathPlaceholder}
              onCommit={(v) => onSettingsChange({ museScorePath: v })}
              trailing={
                <StatusBadge tone={museBadge.tone} label={museBadge.label} />
              }
            />
          </>
        );

      case "tools":
        return (
          <>
            <div className="hs-settings__tool">
              <div className="hs-settings__tool-head">
                <span className="hs-settings__tool-name">FFmpeg</span>
                <StatusBadge
                  tone={ffmpegBadge.tone}
                  label={ffmpegBadge.label}
                />
              </div>
              <p className="hs-settings__note">
                {ja.dependencies.ffmpeg.purpose}
              </p>
              <PathField
                label={s.ffmpegPath}
                value={settings.ffmpegPath}
                placeholder={s.pathPlaceholder}
                onCommit={(v) => onSettingsChange({ ffmpegPath: v })}
              />
            </div>
            <div className="hs-settings__tool">
              <div className="hs-settings__tool-head">
                <span className="hs-settings__tool-name">MuseScore</span>
                <StatusBadge
                  tone={museBadge.tone}
                  label={museBadge.label}
                />
              </div>
              <p className="hs-settings__note">
                {ja.dependencies.musescore.purpose}
              </p>
              <PathField
                label={s.musescorePath}
                value={settings.museScorePath}
                placeholder={s.pathPlaceholder}
                onCommit={(v) => onSettingsChange({ museScorePath: v })}
              />
            </div>
            <div className="hs-settings__field">
              <Label>{s.modelInfo}</Label>
              <p className="hs-settings__value">
                {diag?.backend ?? ja.diagnostics.notConnected}
              </p>
            </div>
          </>
        );

      case "advanced":
        return (
          <>
            <HsSelect
              label={s.backendLabel}
              value={settings.backend}
              options={[
                { value: "auto", label: s.tempoAuto },
                { value: "basicPitch", label: "Basic Pitch" },
              ]}
              onChange={(v) =>
                onSettingsChange({
                  backend: v === "basicPitch" ? "basicPitch" : "auto",
                })
              }
            />
            <div className="hs-settings__field">
              <Label>{s.cache}</Label>
              <p className="hs-settings__value">
                {diag?.paths.cache ?? ja.diagnostics.notConnected}
              </p>
            </div>
            <div className="hs-settings__field">
              <Label>{s.logs}</Label>
              <div className="hs-settings__path-row">
                <p className="hs-settings__value">
                  {diag?.paths.logs ?? ja.diagnostics.notConnected}
                </p>
                <HsButton
                  size="small"
                  onClick={() => void openLogs()}
                >
                  {s.openLogs}
                </HsButton>
              </div>
            </div>
            <div className="hs-settings__field">
              <HsButton onClick={onOpenDiagnostics}>
                {s.openDiagnostics}
              </HsButton>
            </div>
          </>
        );
    }
  })();

  return (
    <div
      className="hs-settings"
      role="region"
      aria-label={s.regionLabel}
      data-hs-focus-zone="settings"
      tabIndex={-1}
    >
      <HsButton
        variant="subtle"
        icon={<ArrowLeft24Regular />}
        onClick={onBack}
      >
        {s.back}
      </HsButton>
      <h1 className="hs-settings__title">{s.title}</h1>

      <div className="hs-settings__layout">
        <nav className="hs-settings__nav" aria-label={s.navLabel}>
          {SETTINGS_CATEGORIES.map((c) => (
            <button
              key={c}
              type="button"
              className={mergeClasses(
                "hs-settings__nav-item",
                c === category && "hs-settings__nav-item--active",
              )}
              aria-current={c === category ? "true" : undefined}
              onClick={() => setCategory(c)}
            >
              {CATEGORY_LABEL[c]}
            </button>
          ))}
        </nav>

        <div className="hs-settings__content">
          <HsPanel
            key={category}
            title={CATEGORY_LABEL[category]}
            titleLevel={2}
            className="hs-settings__section"
          >
            <div className="hs-settings__fields">{section}</div>
          </HsPanel>
        </div>
      </div>

      {/* #78: 録音の全削除は破壊的操作 — alert 確認を挟む。 */}
      <HsDialog
        open={clearConfirmOpen}
        modalType="alert"
        title={s.recordingsClearConfirmTitle}
        onOpenChange={(open) => {
          if (!open) setClearConfirmOpen(false);
        }}
        actions={
          <>
            <HsButton
              variant="danger"
              onClick={() => {
                setClearConfirmOpen(false);
                void clearRecordings().then((freed) => {
                  if (freed !== null) {
                    onAnnounce(
                      `${s.recordingsCleared} (${formatBytes(freed)})`,
                    );
                  }
                  refreshRecordings();
                });
              }}
            >
              {s.recordingsClearConfirm}
            </HsButton>
            <HsButton
              variant="secondary"
              onClick={() => setClearConfirmOpen(false)}
            >
              {ja.capture.replaceCancel}
            </HsButton>
          </>
        }
      >
        <p style={{ margin: 0 }}>{s.recordingsClearConfirmBody}</p>
      </HsDialog>

      {/* #78: 個別削除も破壊的 — ファイル名を明示して確認する。 */}
      <HsDialog
        open={deleteTarget !== null}
        modalType="alert"
        title={s.recordingsDeleteConfirmTitle}
        onOpenChange={(open) => {
          if (!open) setDeleteTarget(null);
        }}
        actions={
          <>
            <HsButton
              variant="danger"
              onClick={() => {
                const name = deleteTarget;
                setDeleteTarget(null);
                if (name) {
                  void deleteRecording(name).then((ok) => {
                    if (ok) onAnnounce(s.recordingsDeleted);
                    refreshRecordings();
                  });
                }
              }}
            >
              {s.recordingsDelete}
            </HsButton>
            <HsButton
              variant="secondary"
              onClick={() => setDeleteTarget(null)}
            >
              {ja.capture.replaceCancel}
            </HsButton>
          </>
        }
      >
        <p style={{ margin: 0 }}>
          {deleteTarget ? s.recordingsDeleteConfirmBody(deleteTarget) : ""}
        </p>
      </HsDialog>
    </div>
  );
}

/**
 * Import-owned score-region bodies (UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * ScoreWorkspace delegates the import-side machine states here:
 *   empty         → drop headline + 開く CTA + formats + trust + recents
 *   openingAudio  → honest indeterminate progress (§5: no fake %)
 *   audioReady    → file metadata + 採譜を開始 + 採譜オプション popover
 *   audioError    → copy-deck error card (別のファイルを選ぶ / 閉じる)
 *   sourceMissing → 元音源が見つかりません card (音源を指定 / 閉じる)
 *
 * All copy resolves through ja.import / ja.emptyState / ja.score — the
 * copy deck (protocol/copy/ja-JP.json) is the source of truth.
 */
import {
  ErrorCircle24Regular,
  FolderOpen24Regular,
  History24Regular,
  Play24Regular,
  Mic24Regular,
  Speaker2Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { HsButton } from "../components/primitives/Button";
import { HsNumericField } from "../components/primitives/NumericField";
import { HsPopover } from "../components/primitives/Popover";
import { HsProgress } from "../components/primitives/Progress";
import { HsSelect, type HsSelectOption } from "../components/primitives/Select";
import type { ScreenState } from "../workspace/screen";
import { formatBytes, formatDuration } from "./format";
import type {
  ImportIssue,
  LoadedAudio,
  RecentProjectEntry,
  SourceMissingInfo,
  TranscriptionOptions,
} from "./types";
import { issueText, type CaptureState } from "../capture/controller";

/** Everything the import-owned bodies need — assembled once in App and
 *  handed down through ScoreWorkspace (keeps that shared file's diff small
 *  for the sibling feature teams). */
export interface ImportView {
  audio: LoadedAudio | null;
  openingLabel: string | null;
  openingKind: "audio" | "project" | null;
  /** AUDIO_ERROR card content (no-audio failures). */
  issue: ImportIssue | null;
  /** SOURCE_MISSING context (project + last relink outcome). */
  sourceMissing: SourceMissingInfo | null;
  recentProjects: readonly RecentProjectEntry[];
  options: TranscriptionOptions;
  onOpenAudio(): void;
  onOpenProject(entry: RecentProjectEntry): void;
  onPickRelink(): void;
  onDismissError(): void;
  onOptionsChange(next: TranscriptionOptions): void;
  /** FEAT-001 (#60): capture controls on the EMPTY state. */
  captureState?: CaptureState | null;
  onStartCapture?(source: "loopback" | "microphone"): void;
}

/** Routes the import-owned screen states to their bodies. */
export function ImportScreenBody({
  screen,
  view,
  onTranscribe,
}: {
  screen: ScreenState;
  view: ImportView;
  onTranscribe(): void;
}) {
  switch (screen) {
    case "empty":
      return <EmptyStateBody view={view} />;
    case "openingAudio":
      return <OpeningAudioBody view={view} />;
    case "audioReady":
      return <AudioReadyBody view={view} onTranscribe={onTranscribe} />;
    case "audioError":
      return <AudioErrorBody view={view} />;
    case "sourceMissing":
      return <SourceMissingBody view={view} />;
    default:
      return null;
  }
}

/* ------------------------------ EMPTY (§3) ------------------------------ */

function EmptyStateBody({ view }: { view: ImportView }) {
  return (
    <div className="hs-empty">
      <p className="hs-empty__title">{ja.emptyState.title}</p>
      <p className="hs-empty__or">{ja.emptyState.or}</p>
      <HsButton
        variant="primary"
        size="large"
        icon={<FolderOpen24Regular />}
        onClick={view.onOpenAudio}
      >
        {ja.emptyState.open}
      </HsButton>
      <p className="hs-empty__formats">{ja.emptyState.formats}</p>
      {/* FEAT-001: 録音による取り込み — ファイルを持たない入力経路。 */}
      {view.onStartCapture ? (
        <div className="hs-empty__capture">
          <p className="hs-empty__capture-title">
            {ja.emptyState.captureTitle}
          </p>
          <div className="hs-empty__capture-actions">
            <HsButton
              variant="secondary"
              icon={<Speaker2Regular />}
              disabled={view.captureState?.phase === "recording"}
              onClick={() => view.onStartCapture!("loopback")}
            >
              {ja.emptyState.captureLoopback}
            </HsButton>
            <HsButton
              variant="secondary"
              icon={<Mic24Regular />}
              disabled={view.captureState?.phase === "recording"}
              onClick={() => view.onStartCapture!("microphone")}
            >
              {ja.emptyState.captureMic}
            </HsButton>
          </div>
          <p className="hs-empty__capture-hint">
            {ja.emptyState.captureHint}
          </p>
          {/* 録音開始の失敗(デバイス無し等)はここに表示する —
              ステータス行だけでは EMPTY 画面で見落とされる。 */}
          {view.captureState?.phase === "error" &&
          view.captureState.issue ? (
            <p className="hs-empty__capture-error" role="alert">
              {issueText(view.captureState.issue)}
            </p>
          ) : null}
        </div>
      ) : null}
      <p className="hs-empty__privacy">{ja.emptyState.privacy}</p>
      {/* §3: 履歴がある場合のみ「最近使ったプロジェクト」 */}
      {view.recentProjects.length > 0 ? (
        <div
          className="hs-recent"
          role="group"
          aria-label={ja.import.recent.title}
        >
          <p className="hs-recent__title">{ja.import.recent.title}</p>
          <ul className="hs-recent__list">
            {view.recentProjects.map((entry) => (
              <li key={entry.path}>
                <button
                  type="button"
                  className="hs-recent__item"
                  title={entry.path}
                  aria-label={ja.import.recent.openAria(entry.name)}
                  onClick={() => view.onOpenProject(entry)}
                >
                  <History24Regular aria-hidden="true" />
                  <span className="hs-recent__name">{entry.name}</span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      ) : null}
    </div>
  );
}

/* --------------------------- OPENING_AUDIO --------------------------- */

function OpeningAudioBody({ view }: { view: ImportView }) {
  const title =
    view.openingKind === "project"
      ? ja.import.opening.project
      : ja.import.opening.audio;
  return (
    <div className="hs-empty hs-opening" role="status">
      <p className="hs-opening__title">{title}</p>
      {/* §5: indeterminate — decode time is not honestly predictable. */}
      <HsProgress label={title} className="hs-opening__progress" />
      {view.openingLabel ? (
        <p className="hs-opening__name">{view.openingLabel}</p>
      ) : null}
    </div>
  );
}

/* --------------------------- AUDIO_READY (§4) --------------------------- */

const TEMPO_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.tempoAuto },
  { value: "manual", label: ja.import.audioOptions.tempoManual },
];
const METER_OPTIONS: readonly HsSelectOption[] = [
  { value: "4/4", label: "4/4" },
  { value: "3/4", label: "3/4" },
  { value: "6/8", label: "6/8" },
  { value: "2/4", label: "2/4" },
  { value: "5/4", label: "5/4" },
  { value: "7/8", label: "7/8" },
];
const MIN_DURATION_OPTIONS: readonly HsSelectOption[] = [
  { value: "8", label: ja.import.audioOptions.minDuration8 },
  { value: "16", label: ja.import.audioOptions.minDuration16 },
  { value: "32", label: ja.import.audioOptions.minDuration32 },
];
const TRIPLET_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.tripletsAuto },
  { value: "allow", label: ja.import.audioOptions.tripletsAllow },
  { value: "none", label: ja.import.audioOptions.tripletsNone },
];
const SIMPLICITY_OPTIONS: readonly HsSelectOption[] = [
  { value: "standard", label: ja.import.audioOptions.simplicityStandard },
  { value: "simple", label: ja.import.audioOptions.simplicitySimple },
  { value: "detailed", label: ja.import.audioOptions.simplicityDetailed },
];
const RANGE_OPTIONS: readonly HsSelectOption[] = [
  { value: "all", label: ja.import.audioOptions.rangeAll },
  // #88: 時刻指定の範囲採譜。波形ドラッグ選択は別issueで検討中だが、
  // 秒数入力だけでも「ソロ部分だけ採譜」は実用になる。
  { value: "selection", label: ja.import.audioOptions.rangeSelection },
];

function AudioReadyBody({
  view,
  onTranscribe,
}: {
  view: ImportView;
  onTranscribe(): void;
}) {
  const { audio, options } = view;
  const set = (patch: Partial<TranscriptionOptions>) =>
    view.onOptionsChange({ ...options, ...patch });
  return (
    <div className="hs-empty hs-audio-ready">
      <p className="hs-score__empty-title">{ja.score.empty}</p>
      {audio ? (
        <p className="hs-audio-ready__meta">
          <span className="hs-audio-ready__name">{audio.fileName}</span>
          <span aria-hidden="true">・</span>
          <span>{audio.format.toUpperCase()}</span>
          <span aria-hidden="true">・</span>
          <span>{formatDuration(audio.durationSeconds)}</span>
          <span aria-hidden="true">・</span>
          <span>{formatBytes(audio.sizeBytes)}</span>
        </p>
      ) : null}
      <div className="hs-audio-ready__actions">
        <HsButton
          variant="primary"
          size="large"
          icon={<Play24Regular />}
          onClick={onTranscribe}
        >
          {ja.score.transcribeStart}
        </HsButton>
        {/* §4: advanced transcription settings live in the popover next to
            the primary action — hidden by default. */}
        <HsPopover
          ariaLabel={ja.import.audioOptions.label}
          positioning="above"
          trigger={
            <HsButton variant="subtle">
              {ja.import.audioOptions.label}
            </HsButton>
          }
        >
          <div className="hs-audio-options">
            <p className="hs-audio-options__title">
              {ja.import.audioOptions.label}
            </p>
            <HsSelect
              label={ja.import.audioOptions.tempo}
              options={TEMPO_OPTIONS}
              value={options.tempo}
              onChange={(v) =>
                set({ tempo: v as TranscriptionOptions["tempo"] })
              }
            />
            {options.tempo === "manual" ? (
              <HsNumericField
                label={ja.import.audioOptions.tempoBpm}
                value={options.tempoBpm}
                min={30}
                max={300}
                step={1}
                unit="BPM"
                onChange={(v) => set({ tempoBpm: v })}
              />
            ) : null}
            <HsSelect
              label={ja.import.audioOptions.meter}
              options={METER_OPTIONS}
              value={options.meter}
              onChange={(v) => set({ meter: v })}
            />
            <HsSelect
              label={ja.import.audioOptions.minDuration}
              options={MIN_DURATION_OPTIONS}
              value={options.minDuration}
              onChange={(v) => set({ minDuration: v })}
            />
            <HsSelect
              label={ja.import.audioOptions.triplets}
              options={TRIPLET_OPTIONS}
              value={options.triplets}
              onChange={(v) =>
                set({ triplets: v as TranscriptionOptions["triplets"] })
              }
            />
            <HsSelect
              label={ja.import.audioOptions.simplicity}
              options={SIMPLICITY_OPTIONS}
              value={options.simplicity}
              onChange={(v) =>
                set({ simplicity: v as TranscriptionOptions["simplicity"] })
              }
            />
            <HsSelect
              label={ja.import.audioOptions.range}
              options={RANGE_OPTIONS}
              value={options.range}
              onChange={(v) =>
                set({ range: v as TranscriptionOptions["range"] })
              }
            />
            {options.range === "selection" && audio ? (
              <>
                <HsNumericField
                  label={ja.import.audioOptions.rangeStart}
                  value={options.selectionStartSec}
                  min={0}
                  max={audio.durationSeconds}
                  step={0.5}
                  unit={ja.import.audioOptions.secondsUnit}
                  onChange={(v) => set({ selectionStartSec: v })}
                />
                <HsNumericField
                  label={ja.import.audioOptions.rangeEnd}
                  value={options.selectionEndSec}
                  min={0}
                  max={audio.durationSeconds}
                  step={0.5}
                  unit={ja.import.audioOptions.secondsUnit}
                  onChange={(v) => set({ selectionEndSec: v })}
                />
              </>
            ) : null}
          </div>
        </HsPopover>
      </div>
    </div>
  );
}

/* ------------------------------ errors (§20) ------------------------------ */

/** Copy-deck error copy per issue kind — shared by the AUDIO_ERROR card
 *  and the modal dialog shown when a re-import fails over a live session. */
export function issueCopy(issue: ImportIssue): {
  title: string;
  body: string;
  fileName?: string;
} {
  switch (issue.kind) {
    case "unsupported":
      return {
        title: ja.import.errors.unsupportedTitle,
        body: ja.import.errors.unsupportedBody,
        fileName: issue.fileName,
      };
    case "openFailed":
      return {
        title: ja.import.errors.openFailedTitle,
        body: ja.import.errors.openFailedBody,
        fileName: issue.fileName,
      };
    case "projectOpenFailed":
      return {
        title: ja.import.errors.projectOpenFailedTitle,
        body: ja.import.errors.projectOpenFailedBody,
        fileName: issue.fileName,
      };
  }
}

function AudioErrorBody({ view }: { view: ImportView }) {
  const issue = view.issue ?? { kind: "openFailed" as const };
  const copy = issueCopy(issue);
  const canPickAnother = issue.kind !== "projectOpenFailed";
  return (
    <div className="hs-empty hs-error" role="alert">
      <ErrorCircle24Regular
        className="hs-error__icon"
        aria-hidden="true"
      />
      <p className="hs-error__title">{copy.title}</p>
      {copy.fileName ? (
        <p className="hs-error__file">{copy.fileName}</p>
      ) : null}
      <p className="hs-error__body">{copy.body}</p>
      <div className="hs-error__actions">
        {canPickAnother ? (
          <HsButton variant="primary" onClick={view.onOpenAudio}>
            {ja.import.errors.chooseAnother}
          </HsButton>
        ) : null}
        <HsButton
          variant={canPickAnother ? "secondary" : "primary"}
          onClick={view.onDismissError}
        >
          {ja.import.errors.close}
        </HsButton>
      </div>
    </div>
  );
}

function SourceMissingBody({ view }: { view: ImportView }) {
  const info = view.sourceMissing;
  const mismatch = info?.mismatch === true;
  return (
    <div className="hs-empty hs-error" role="alert">
      <ErrorCircle24Regular
        className="hs-error__icon"
        aria-hidden="true"
      />
      <p className="hs-error__title">
        {mismatch
          ? ja.import.errors.hashMismatchTitle
          : ja.import.errors.sourceMissingTitle}
      </p>
      {info?.project.sourcePath ? (
        <p className="hs-error__file" title={info.project.sourcePath}>
          {ja.import.errors.lastLocation}
          {info.project.sourcePath}
        </p>
      ) : null}
      <p className="hs-error__body">
        {mismatch
          ? ja.import.errors.hashMismatchBody
          : ja.import.errors.sourceMissingBody}
      </p>
      <div className="hs-error__actions">
        <HsButton variant="primary" onClick={view.onPickRelink}>
          {mismatch
            ? ja.import.errors.specifyAnother
            : ja.import.errors.specifySource}
        </HsButton>
        <HsButton variant="secondary" onClick={view.onDismissError}>
          {ja.import.errors.close}
        </HsButton>
      </div>
    </div>
  );
}

/**
 * Build the `job.start` params for the real `transcription` job kind
 * (ENG-002) from the loaded audio + the 採譜オプション popover state.
 *
 * Wire contract (python/hornscribe/transcription/options.py):
 * `audioPath` is required — the engine reads the file itself, so only
 * refs backed by a real path can drive a real job:
 *
 * - `kind:"path"` (native dialog / native drop) -> the path itself;
 * - `kind:"recording"` with `path` (Tauri capture: the WAV was already
 *   persisted under appDataDir/recordings/) -> that path;
 * - `kind:"file"` (browser dev drop) and pathless recordings -> no
 *   audioPath; the mock port ignores params anyway, so dev sessions
 *   still exercise the flow. A future staging step can copy browser
 *   bytes to a temp file (tracked as a follow-up issue).
 *
 * `tempoBpm` is only sent for manual tempo — auto omits it so the
 * engine runs beat tracking. `range:"selection"` sends the user's
 * start/end seconds, clamped to the clip duration.
 */
import type {
  AudioFileRef,
  LoadedAudio,
  RecordedAudioRef,
  TranscriptionOptions,
} from "./types";

function audioPathOf(ref: AudioFileRef | RecordedAudioRef): string | null {
  if (ref.kind === "path") return ref.path;
  if (ref.kind === "recording") return ref.path ?? null;
  return null; // kind === "file": browser dev, no on-disk source
}

export interface TranscriptionJobParams {
  audioPath?: string;
  tempoBpm?: number;
  meter?: string;
  minDuration?: string;
  triplets?: string;
  simplicity?: string;
  range?: string;
  selectionStartSec?: number;
  selectionEndSec?: number;
}

export function buildTranscriptionParams(
  audio: LoadedAudio | null,
  options: TranscriptionOptions,
): TranscriptionJobParams {
  const params: TranscriptionJobParams = {};
  const path = audio ? audioPathOf(audio.ref) : null;
  if (path) params.audioPath = path;

  if (options.tempo === "manual" && options.tempoBpm != null) {
    params.tempoBpm = options.tempoBpm;
  }
  // "auto" meter is the engine default; only pin an explicit choice.
  if (options.meter && options.meter !== "auto") {
    params.meter = options.meter;
  }
  if (options.minDuration) params.minDuration = options.minDuration;
  if (options.triplets !== "auto") params.triplets = options.triplets;
  if (options.simplicity !== "standard") {
    params.simplicity = options.simplicity;
  }
  if (options.range === "selection") {
    params.range = "selection";
    // The engine requires end > start for selection mode; clamp the
    // user's seconds into [0, duration] and fall back to the full span
    // when the pair is empty or inverted.
    const dur = audio?.durationSeconds ?? 0;
    let start = options.selectionStartSec ?? 0;
    let end = options.selectionEndSec ?? dur;
    start = Math.min(Math.max(start, 0), dur);
    end = Math.min(Math.max(end, 0), dur);
    if (end <= start) {
      start = 0;
      end = dur;
    }
    params.selectionStartSec = start;
    params.selectionEndSec = end;
  }
  return params;
}

/**
 * Import domain types (issue #25 / UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * The import flow turns a user-picked file into a `LoadedAudio` the shell
 * can draw (waveform peaks + metadata) and play (UI-004 TransportController
 * contract media source), or into a recoverable `ImportIssue` rendered with
 * the copy-deck error shape (what failed / what is kept / next action).
 */

/** Advertised container formats (GUI_UX_SPEC §3: WAV・MP3・FLAC・M4A・OGG). */
export type AudioFormat = "wav" | "mp3" | "flac" | "m4a" | "ogg";

/**
 * A user-selected audio file. Inside Tauri the native dialog and the
 * window drag-drop event hand us real filesystem paths; in plain-browser
 * dev sessions the HTML drop/file-input hands us `File` objects.
 */
export type AudioFileRef =
  | { kind: "path"; path: string; name: string }
  | { kind: "file"; file: File; name: string };

/**
 * FEAT-001 (#60): 録音由来の疑似ファイル参照。
 * `kind: "recording"` はディスク上の実ファイルではなく、メモリ上の
 * 録音バッファを表す。`mediaSource.blob` に録音結果が入るので、
 * `LoadedAudio` としては既存経路と同じ振る舞いをする。
 */
export type RecordedAudioRef = {
  kind: "recording";
  /** UI 表示用の仮想ファイル名(例: "録音_20260922_153000.wav")。 */
  name: string;
  /** "loopback" | "microphone" — どこから録ったか。 */
  source: "loopback" | "microphone";
  /** Tauri: appDataDir/recordings/ に保存済みの実ファイルパス(#70)。
   *  ある場合は内容がディスク上に永続化されており、プロジェクトの
   *  sourceAudio(originalPath/contentHash)に載せられる。 */
  path?: string;
  /** path を持つ録音の SHA-256(FND-001 の contentHash 契約)。 */
  contentHash?: string;
  /** ブラウザ dev 等、実ファイルが無い場合の録音バイト列。 */
  blob?: Blob;
};

/**
 * What the UI-004 TransportController contract can load — mirrors the
 * spike's `AudioSource` (url | blob). We always hand over a blob: either
 * the dropped `File` itself or a Blob built from `read_audio_bytes`, so the
 * user-owned source file is only ever read, never modified.
 */
export type MediaSource = { kind: "url"; url: string } | { kind: "blob"; blob: Blob };

/** Fully decoded audio ready for the AUDIO_READY state (GUI_UX_SPEC §4). */
export interface LoadedAudio {
  /** Where the bytes came from (kept for relink/re-open bookkeeping). */
  ref: AudioFileRef | RecordedAudioRef;
  fileName: string;
  format: AudioFormat;
  sizeBytes: number;
  /** Audio-clock duration in seconds (0 while unknown). */
  durationSeconds: number;
  sampleRate: number;
  /** Normalized peak amplitudes 0–1 for the waveform strip. */
  peaks: readonly number[];
  /** Playback-ready source for the transport adapter. */
  mediaSource: MediaSource;
}

/**
 * Recoverable import failures — every variant has a copy-deck title/body
 * plus a recovery action, so errors never dead-end (acceptance: "invalid
 * file has actionable Japanese error", "unsupported codec does not
 * dead-end").
 */
export type ImportIssue =
  /** Extension is not in the advertised set — honest format guidance. */
  | { kind: "unsupported"; fileName: string }
  /** Read/decode failed (corrupt file, vanished path, codec the webview
      cannot decode and FFmpeg normalization has not landed yet). */
  | { kind: "openFailed"; fileName?: string }
  /** `.hornscribe.json` could not be read or parsed. */
  | { kind: "projectOpenFailed"; fileName: string };

/**
 * The subset of `HornScribeProject` (python/hornscribe/project/model.py,
 * schema v1) the relink UX needs. `sourcePath`/`sourceHash` mirror
 * `sourceAudio.originalPath` / `contentHash`.
 */
export interface ProjectSummary {
  /** Absolute path of the .hornscribe.json file itself. */
  path: string;
  projectId: string;
  /** Display name — file basename without the .hornscribe.json suffix. */
  name: string;
  sourcePath: string | null;
  sourceHash: string | null;
}

/** SOURCE_MISSING context: which project lost its audio, and whether the
 *  last relink candidate failed the content-hash check (deck:
 *  sourceMoved vs sourceHashMismatch copy). */
export interface SourceMissingInfo {
  project: ProjectSummary;
  mismatch: boolean;
}

/** A "最近使ったプロジェクト" entry (GUI_UX_SPEC §3). */
export interface RecentProjectEntry {
  name: string;
  path: string;
  /** Epoch ms of the last successful open (sorting + pruning). */
  openedAt: number;
}

/**
 * 採譜オプション (GUI_UX_SPEC §4 advanced options — hidden in the popover
 * next to 採譜を開始). Values are option keys; Japanese labels resolve via
 * ja.import.audioOptions. Consumed by the transcription feature (UI-040),
 * persisted nowhere yet.
 */
export interface TranscriptionOptions {
  tempo: "auto" | "manual";
  tempoBpm: number | null;
  meter: string;
  minDuration: string;
  triplets: "auto" | "allow" | "none";
  simplicity: "standard" | "simple" | "detailed";
  range: "all" | "selection";
  /** 範囲指定時の開始/終了（秒）。null = 音声の端まで。 */
  selectionStartSec: number | null;
  selectionEndSec: number | null;
}

export const DEFAULT_TRANSCRIPTION_OPTIONS: TranscriptionOptions = {
  tempo: "auto",
  tempoBpm: null,
  meter: "4/4",
  minDuration: "16",
  triplets: "auto",
  simplicity: "standard",
  range: "all",
  selectionStartSec: null,
  selectionEndSec: null,
};

/**
 * Settings persistence (UI-060; GUI_UX_SPEC §18/§26).
 *
 * User-facing settings live in one localStorage record (mirroring the
 * existing `hornscribe.theme` / layout persistence — best-effort, never
 * crashes when storage is unavailable or holds stale/foreign data).
 * Only known keys are merged back and every value is re-validated, so a
 * corrupt or newer-version blob degrades to defaults field by field.
 *
 * NO language setting exists — the UI is Japanese-only by contract.
 */

import { useCallback, useMemo, useState } from "react";

const STORAGE_KEY = "hornscribe.settings";

/** The §18 categories in display order (録音 sits between 再生 and 採譜). */
export const SETTINGS_CATEGORIES = [
  "appearance",
  "playback",
  "recordings",
  "transcription",
  "score",
  "export",
  "tools",
  "advanced",
] as const;

export type SettingsCategory = (typeof SETTINGS_CATEGORIES)[number];

export type TempoMode = "auto" | "manual";
export type MeterSetting = "auto" | "4/4" | "3/4" | "6/8" | "2/4" | "5/4";
export type MinDurationSetting = "eighth" | "sixteenth" | "thirtySecond";
export type ScoreViewMode = "continuous" | "page";
export type BackendSetting = "auto" | "basicPitch";

export interface AppSettings {
  /** 再生 → 標準再生速度 (0.5–2.0). */
  readonly playbackRate: number;
  /** 再生 → 戻る/進む秒数. */
  readonly skipSeconds: number;
  /** 再生 → 再生位置を追従. */
  readonly followPlayback: boolean;
  /** 採譜 → テンポ auto/manual + BPM value. */
  readonly tempoMode: TempoMode;
  readonly bpm: number;
  /** 採譜 → 拍子. */
  readonly meter: MeterSetting;
  /** 採譜 → 最小音価. */
  readonly minDuration: MinDurationSetting;
  /** 採譜 → 三連符を使う. */
  readonly triplets: boolean;
  /** 楽譜 → 初期表示. */
  readonly scoreInitialView: ScoreViewMode;
  /** 書き出し → 既定の保存先 ("" = choose at export time). */
  readonly defaultExportDir: string;
  /** 書き出し → MuseScoreの場所 ("" = auto-detect). */
  readonly museScorePath: string;
  /** ツール → FFmpegの場所 ("" = auto-detect). */
  readonly ffmpegPath: string;
  /** 詳細設定 → 採譜エンジン. */
  readonly backend: BackendSetting;
  /** 録音 → 自動削除の保持日数 (0 = 削除しない). */
  readonly recordingsRetentionDays: number;
}

export const DEFAULT_SETTINGS: AppSettings = {
  playbackRate: 1,
  skipSeconds: 5,
  followPlayback: true,
  tempoMode: "auto",
  bpm: 120,
  meter: "auto",
  minDuration: "sixteenth",
  triplets: true,
  scoreInitialView: "continuous",
  defaultExportDir: "",
  museScorePath: "",
  ffmpegPath: "",
  backend: "auto",
  recordingsRetentionDays: 0,
};

const RATES = [0.5, 0.75, 1, 1.25, 1.5, 2];
const METERS: readonly MeterSetting[] = [
  "auto",
  "4/4",
  "3/4",
  "6/8",
  "2/4",
  "5/4",
];
const MIN_DURATIONS: readonly MinDurationSetting[] = [
  "eighth",
  "sixteenth",
  "thirtySecond",
];
const VIEWS: readonly ScoreViewMode[] = ["continuous", "page"];
const BACKENDS: readonly BackendSetting[] = ["auto", "basicPitch"];

function num(v: unknown, min: number, max: number): number | null {
  return typeof v === "number" && Number.isFinite(v) && v >= min && v <= max
    ? v
    : null;
}
function str(v: unknown): string | null {
  return typeof v === "string" ? v : null;
}
function bool(v: unknown): boolean | null {
  return typeof v === "boolean" ? v : null;
}
function oneOf<T extends string>(v: unknown, list: readonly T[]): T | null {
  return typeof v === "string" && (list as readonly string[]).includes(v)
    ? (v as T)
    : null;
}

/** Parse + validate the stored blob; unknown/invalid fields get defaults. */
export function parseSettings(raw: string | null): AppSettings {
  if (!raw) return DEFAULT_SETTINGS;
  let o: Record<string, unknown>;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null) return DEFAULT_SETTINGS;
    o = parsed as Record<string, unknown>;
  } catch {
    return DEFAULT_SETTINGS;
  }
  const d = DEFAULT_SETTINGS;
  return {
    playbackRate: num(o.playbackRate, 0.25, 4) ?? d.playbackRate,
    skipSeconds: num(o.skipSeconds, 1, 60) ?? d.skipSeconds,
    followPlayback: bool(o.followPlayback) ?? d.followPlayback,
    tempoMode: oneOf(o.tempoMode, ["auto", "manual"]) ?? d.tempoMode,
    bpm: num(o.bpm, 30, 300) ?? d.bpm,
    meter: oneOf(o.meter, METERS) ?? d.meter,
    minDuration: oneOf(o.minDuration, MIN_DURATIONS) ?? d.minDuration,
    triplets: bool(o.triplets) ?? d.triplets,
    scoreInitialView: oneOf(o.scoreInitialView, VIEWS) ?? d.scoreInitialView,
    defaultExportDir: str(o.defaultExportDir) ?? d.defaultExportDir,
    museScorePath: str(o.museScorePath) ?? d.museScorePath,
    ffmpegPath: str(o.ffmpegPath) ?? d.ffmpegPath,
    backend: oneOf(o.backend, BACKENDS) ?? d.backend,
    recordingsRetentionDays:
      num(o.recordingsRetentionDays, 0, 3650) ?? d.recordingsRetentionDays,
  };
}

export function loadSettings(): AppSettings {
  try {
    return parseSettings(window.localStorage.getItem(STORAGE_KEY));
  } catch {
    return DEFAULT_SETTINGS;
  }
}

export function saveSettings(settings: AppSettings): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch {
    /* persistence is best-effort — the session keeps working */
  }
}

/** Valid playback-rate options surfaced in 設定 → 再生. */
export function playbackRateOptions(): readonly number[] {
  return RATES;
}

/**
 * React binding: current settings + a merge-style updater that persists
 * immediately (the theme switcher sets the precedent — changes apply at
 * once, no save button).
 */
export function useAppSettings(): {
  settings: AppSettings;
  update: (patch: Partial<AppSettings>) => void;
} {
  const [settings, setSettings] = useState<AppSettings>(loadSettings);
  const update = useCallback((patch: Partial<AppSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      saveSettings(next);
      return next;
    });
  }, []);
  return useMemo(() => ({ settings, update }), [settings, update]);
}
